import{_ as e,c as a,o as t,a4 as i}from"./chunks/framework.CRCV4hx_.js";const m=JSON.parse('{"title":"Resrv Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),o={name:"changelog.md"},r=i('<h1 id="resrv-changelog" tabindex="-1">Resrv Changelog <a class="header-anchor" href="#resrv-changelog" aria-label="Permalink to &quot;Resrv Changelog&quot;">​</a></h1><h2 id="v6-0-0" tabindex="-1">v6.0.0 <a class="header-anchor" href="#v6-0-0" aria-label="Permalink to &quot;v6.0.0&quot;">​</a></h2><h4 id="release-date-june-2026" tabindex="-1">Release date: June 2026 <a class="header-anchor" href="#release-date-june-2026" aria-label="Permalink to &quot;Release date: June 2026&quot;">​</a></h4><h3 id="this-is-a-major-release-with-breaking-changes-please-read-the-upgrade-guide-and-back-up-your-database-before-upgrading" tabindex="-1">This is a major release with breaking changes. Please read the <a href="./upgrading">Upgrade Guide</a> and back up your database before upgrading. <a class="header-anchor" href="#this-is-a-major-release-with-breaking-changes-please-read-the-upgrade-guide-and-back-up-your-database-before-upgrading" aria-label="Permalink to &quot;This is a major release with breaking changes. Please read the [Upgrade Guide](./upgrading) and back up your database before upgrading.&quot;">​</a></h3><p>Resrv v6 brings the add-on to Statamic 6, introduces the new Rates system, adds multiple payment gateways, and rebuilds the Control Panel.</p><h3 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h3><ul><li>PHP 8.4+</li><li>Laravel 12 or 13</li><li>Statamic 6</li><li>Livewire 3.6.4+ or 4</li></ul><h3 id="new-features" tabindex="-1">New features <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;New features&quot;">​</a></h3><ul><li><strong><a href="./rates">Rates</a>:</strong> a new collection-scoped rate system that replaces the old per-entry &quot;advanced availability&quot; and &quot;connected availabilities&quot;. Rates support independent or relative pricing, independent or shared inventory, date and stay restrictions, per-rate cancellation policies, and selective entry assignment.</li><li><strong><a href="./payment-gateways">Multiple payment gateways</a>:</strong> offer several payment methods at checkout with a gateway picker, a built-in offline (bank transfer / pay-at-premises) gateway, per-gateway surcharges and amount limits, and per-gateway webhooks. A documented interface lets you <a href="./custom-payment-gateway">build your own gateway</a>.</li><li><strong>New frontend components:</strong> <a href="./availability-search-multiple#the-availability-collection-component"><code>availability-collection</code></a> (a live, no-extra-package list of available entries for a whole collection), <a href="./cart-booking"><code>availability-multi-results</code></a> (cart-based multi-rate / multi-date booking), and <a href="./availability-list"><code>availability-list</code></a> (a list of upcoming available dates).</li><li><strong><a href="./configuration">Settings in the Control Panel</a>:</strong> business, reservation, checkout, email and currency settings now live under Resrv → Settings. <code>config/resrv-config.php</code> keeps developer-only keys. The <code>php please resrv:settings:migrate</code> command migrates legacy values.</li><li><strong><a href="./emails">Email customization</a>:</strong> configure recipients, subject, from address and template per event and per checkout form, plus opt-in abandoned-reservation recovery emails. The Logo field now renders in emails automatically.</li><li><strong>Per-rate <a href="./rates#cancellation-policy">cancellation policies</a>:</strong> set a free-cancellation window or mark a rate as non-refundable; the policy is shown to the customer and snapshotted onto the reservation.</li><li><strong><a href="./reservations#export">CSV export</a>:</strong> export reservations filtered by date range, status and columns, with custom checkout fields included.</li><li><strong>Reports</strong> can now run against the booking-creation date as well as the reservation date.</li><li><strong>Minimum and maximum <a href="./dynamic-pricing">dynamic pricing</a> rules:</strong> clamp the final price to a floor or ceiling, applied after all other rules and coupons (and to extras).</li><li>The frontend calendar moved to <a href="./frontend-setup"><code>@reachweb/alpine-calendar</code></a> and the Control Panel was rebuilt on Statamic 6 (Vue 3 + Inertia + Tailwind v4).</li></ul><h3 id="breaking-changes" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h3><ul><li>Platform floor raised to PHP 8.4 / Laravel 12–13 / Statamic 6 / Livewire 3.6.4+.</li><li>The <code>property</code> column, <code>advanced_availability</code> and <code>connected_availabilities</code> are removed and replaced by Rates. Run <code>php artisan resrv:upgrade-to-rates</code> after migrating.</li><li>Custom payment gateways must implement five new <code>PaymentInterface</code> methods.</li><li>CP-managed settings move out of <code>config/resrv-config.php</code> into the Control Panel.</li><li>Published frontend views (e.g. <code>availability-advanced</code> → <code>availability-rates</code>), language overrides and the calendar&#39;s CSS variables changed.</li></ul><h3 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h3><p>Follow the full <a href="./upgrading">Upgrade Guide</a>. In short: back up your database, bump your requirements and run <code>composer update</code>, run <code>php artisan migrate</code>, run <code>php please resrv:settings:migrate</code> and <code>php artisan resrv:upgrade-to-rates</code>, then update any published views, language files and custom payment gateways.</p><h2 id="v5-0-0" tabindex="-1">v5.0.0 <a class="header-anchor" href="#v5-0-0" aria-label="Permalink to &quot;v5.0.0&quot;">​</a></h2><h4 id="release-date-5th-dec-2025" tabindex="-1">Release date: 5th Dec 2025 <a class="header-anchor" href="#release-date-5th-dec-2025" aria-label="Permalink to &quot;Release date: 5th Dec 2025&quot;">​</a></h4><h3 id="this-release-contains-breaking-changes-please-read-follow-the-release-notes-to-upgrade-existing-resrv-installations" tabindex="-1">This release contains breaking changes please read follow the release notes to upgrade existing Resrv installations. <a class="header-anchor" href="#this-release-contains-breaking-changes-please-read-follow-the-release-notes-to-upgrade-existing-resrv-installations" aria-label="Permalink to &quot;This release contains breaking changes please read follow the release notes to upgrade existing Resrv installations.&quot;">​</a></h3><h3 id="new-features-1" tabindex="-1">New features <a class="header-anchor" href="#new-features-1" aria-label="Permalink to &quot;New features&quot;">​</a></h3><ul><li>Totally rewritten Extras and Options functionality. Instead of using Blade components this functionality has now been moved into their own Livewire components. This minimizes use of JavaScript in the frontend and results in faster and more secure functionality.</li><li>Added a new &quot;days of the week&quot; setting in the Mass Availability modal that allows you to only apply the changes in specific days of the selected range.</li><li>Added a new <code>availability-results-advanced</code> Blade component that you can use to display all the possible advanced properties and their availability / pricing.</li><li>Added a new <code>Cutoff</code> field that allows you to set a specific start time and schedule for each entry and set a cutoff time in hours after which reservations are no longer possible.</li><li>Added more robust <strong>connected availabilities</strong> rules.</li><li>Changed the <code>$resetAdvancedOnBoot</code> property of <code>AvailabilitySearch</code> to <code>$resetOnBoot</code> and it now also resets the quantity and triggers a search.</li><li>Moved the customer data into a separate Customer model and database table. This will help us create account functionality in the future.</li><li>Moved the availability calendar into a popup in order to provide much better mobile support.</li><li>Removed the need for the Resrv Availability field to have the &quot;resrv_availability&quot; handle in the Statamic blueprints.</li><li>Added a &quot;when extra is NOT selected&quot; condition rule to show / hide / require an extra if another extra is NOT selected.</li><li>Added extra category conditions to show / hide / require extras based on categories.</li><li>Added support for wildcard coupons using <code>*</code> to apply coupons to all entries.</li><li>Added affiliate - coupon relationship to connect affiliates with coupons.</li><li>Added the ability to close the calendar popup with the Esc key.</li><li>Added support for multiple webhook secrets in the payment gateway configuration.</li><li>The payment gateway now passes the public key through for easier frontend configuration.</li><li>Email templates now use the configured logo.</li><li>Made the calendar input readonly to prevent manual text input.</li><li>Use override label in emails and frontend if set.</li></ul><h3 id="bug-fixes" tabindex="-1">Bug fixes <a class="header-anchor" href="#bug-fixes" aria-label="Permalink to &quot;Bug fixes&quot;">​</a></h3><ul><li>Fixed some countries not appearing in the phone codes field of the checkout form.</li><li>Fixed some issues with reservations made on the current day for the same day.</li><li>Fixed an issue where coupons wouldn&#39;t update the total if applied after step 1.</li><li>Fixed affiliate removal when coupon is removed.</li><li>Fixed wildcard coupons on update event.</li><li>Fixed Resrv tag getting schedule for wrong entry.</li><li>Fixed reverse condition for extras.</li><li>Fixed wrong email getter.</li><li>Fixed refund emails being sent multiple times.</li><li>Various other fixes you can find in GitHub.</li></ul><h3 id="upgrading-1" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading-1" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h3><ul><li><strong>Make a backup of your database.</strong></li><li><strong>Migrate your database by running <code>php artisan migrate</code></strong></li><li>The <em>resrv_customers</em> table should now have your customer data. This should be handled automatically by the migration but please check your database afterwards.</li><li>There are <strong>major changes</strong> in Resrv&#39;s frontend views: if you were overriding those you need to manually upgrade the following views: <ul><li><code>checkout.blade.php</code> - needs to be upgraded to use the new Extras and Options components. Check the file in this release to check what needs to be changed.</li><li><code>availability-results.blade.php</code> - also needs to be upgraded to use the new Extras and Options component - <strong>even if you had not enabled them here</strong>.</li><li>Also in <code>availability-results.blade.php</code> you need to add the section for displaying the cutoff feature error if you use it.</li><li><code>checkout-extras.blade.php</code> and <code>checkout-extra.blade.php</code> - These have been completely replaced by <code>extras.blade.php</code> and <code>extra.blade.php</code></li><li><code>checkout-options.blade.php</code> and <code>checkout-option.blade.php</code> - These have been completely replaced by <code>options.blade.php</code> and <code>option.blade.php</code></li><li>If you were using <code>availability-extras.blade.php</code> or <code>availability-options.blade.php</code> they also need to be upgraded.</li><li><code>checkout-payment-table.blade.php</code> needs to be upgraded to use the new Extras and Options objects. Also check the changes in this release.</li></ul></li><li>You also need to update your <strong>email templates</strong> (again if you were overriding those). We have tried to respect backwards compatibility here but changing the following in all email templates is best practice: <ul><li>Any mention of <code>$reservation-&gt;customer-&gt;get(&#39;email)</code> should now be <code>$reservation-&gt;customer-&gt;email</code>.</li><li>Replace <code>$reservation-&gt;customer-&gt;count() &gt; 1</code> with <code>$reservation-&gt;has(&#39;customer&#39;)</code></li><li>Replace <code>@foreach ($reservation-&gt;customer as $field =&gt; $value)</code> with <code>@foreach ($reservation-&gt;customerData as $field =&gt; $value)</code>.</li></ul></li></ul><h2 id="v4-1-0" tabindex="-1">v4.1.0 <a class="header-anchor" href="#v4-1-0" aria-label="Permalink to &quot;v4.1.0&quot;">​</a></h2><h4 id="release-date-18th-mar-2025" tabindex="-1">Release date: 18th Mar 2025 <a class="header-anchor" href="#release-date-18th-mar-2025" aria-label="Permalink to &quot;Release date: 18th Mar 2025&quot;">​</a></h4><ul><li>Laravel 12 support</li><li>Added a fix for the new country code dictionary so that it can be used in regular Statamic forms and pass the value to the email template correctly.</li><li>Cleanup of unused database columns and tables.</li></ul><h2 id="v4-0-1" tabindex="-1">v4.0.1 <a class="header-anchor" href="#v4-0-1" aria-label="Permalink to &quot;v4.0.1&quot;">​</a></h2><h4 id="release-date-1st-mar-2025" tabindex="-1">Release date: 1st Mar 2025 <a class="header-anchor" href="#release-date-1st-mar-2025" aria-label="Permalink to &quot;Release date: 1st Mar 2025&quot;">​</a></h4><ul><li>Fix issues with diffInDays method changing in Carbon v3.</li></ul><h2 id="v4-0-0" tabindex="-1">v4.0.0 <a class="header-anchor" href="#v4-0-0" aria-label="Permalink to &quot;v4.0.0&quot;">​</a></h2><h4 id="release-date-28th-feb-2025" tabindex="-1">Release date: 28th Feb 2025 <a class="header-anchor" href="#release-date-28th-feb-2025" aria-label="Permalink to &quot;Release date: 28th Feb 2025&quot;">​</a></h4><ul><li>New frontend calendar based on <a href="https://vanilla-calendar.pro/" target="_blank" rel="noreferrer">Vanilla Calendar Pro</a>. <ul><li>Added the capability to display price and availability per day inside the calendar itself.</li><li>The calendar now respects minimum and maximum durations and doesn&#39;t allow the user to select an unsupported range.</li></ul></li><li>New extra categories feature: your extras can now belong to categories.</li><li>Extras are now using the <code>Entry</code> model to associate themselves with Entries.</li><li>Extras are no longer editable inside an Entry using the <code>resrv_extras</code> field.</li><li>Full conditional extras support (Show / hide or require extras based on conditions).</li><li>New phone dictionary (both frontend and backend) for the checkout form that displays country phone code select box plus a text input for the phone number.</li><li>Added a <code>resrv:import-entries</code> command that can be used to sync the site&#39;s Entries to Resrv&#39;s database.</li><li>Improved extension&#39;s config display in the control panel and various panels.</li><li>Upgraded the Stripe library to the latest version.</li><li>Various small bug fixes.</li></ul><h3 id="upgrading-2" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading-2" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h3><ul><li><strong>Make a backup of your database.</strong></li><li><strong>Migrate your database by running <code>php artisan migrate</code></strong></li><li>The <em>resrv_statamicentry_extra</em> table is being replaced by the <em>resrv_entry_extra</em> table. This should be handled automatically by the migration but please check your database afterwards.</li><li>There are major changes in Resrv&#39;s frontend views: if you were overriding those you need to manually upgrade the availability-search.blade.php, checkout-extras.blade.php, checkout-extra.blade.php files (and possibly more like the dictionary fields).</li></ul><h2 id="v3-2-0" tabindex="-1">v3.2.0 <a class="header-anchor" href="#v3-2-0" aria-label="Permalink to &quot;v3.2.0&quot;">​</a></h2><h4 id="release-date-1st-oct-2024" tabindex="-1">Release date: 1st Oct 2024 <a class="header-anchor" href="#release-date-1st-oct-2024" aria-label="Permalink to &quot;Release date: 1st Oct 2024&quot;">​</a></h4><ul><li>Removed all the legacy API endpoints, controllers and more.</li><li>Added more tests to cover scenarios that were tested from the API endpoints.</li><li>Fix an issue that when a date range would contain the date that Daylight saving starts, the duration would be a day less.</li></ul><h2 id="v3-1-0" tabindex="-1">v3.1.0 <a class="header-anchor" href="#v3-1-0" aria-label="Permalink to &quot;v3.1.0&quot;">​</a></h2><h4 id="release-date-18th-sept-2024" tabindex="-1">Release date: 18th Sept 2024 <a class="header-anchor" href="#release-date-18th-sept-2024" aria-label="Permalink to &quot;Release date: 18th Sept 2024&quot;">​</a></h4><ul><li>NEW Added support for Dictionaries in your checkout forms so that you can easily add selects with many options, like Countries.</li><li>NEW New AlpineJS component for dictionaries, with filtering.</li><li>FIX The select field was not working on checkout forms due to some changes from Statamic&#39;s side.</li><li>FIX Calendar and Reports will now show and take into account accordingly partner reservations. (made via the affiliate system).</li></ul><h3 id="upgrading-3" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading-3" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h3><p>Please note that if you have already overridden the Resrv views you will need to copy the file dictionary.blade.php from views/livewire/component/fields to your views/vendor/statamic-resrv folder.</p><h2 id="v3-0-1" tabindex="-1">v3.0.1 <a class="header-anchor" href="#v3-0-1" aria-label="Permalink to &quot;v3.0.1&quot;">​</a></h2><h4 id="release-date-9th-sept-2024" tabindex="-1">Release date: 9th Sept 2024 <a class="header-anchor" href="#release-date-9th-sept-2024" aria-label="Permalink to &quot;Release date: 9th Sept 2024&quot;">​</a></h4><ul><li>Fixed an issue when at the first save of an Entry that had a Resrv Availability field as &quot;disabled&quot; the value would not get saved thus making the Entry available to reserve.</li><li>Fixed two issues with Fixed pricing.</li><li>Updated the documentation URL and added the logo.</li></ul><h2 id="v3-0-0" tabindex="-1">v3.0.0 <a class="header-anchor" href="#v3-0-0" aria-label="Permalink to &quot;v3.0.0&quot;">​</a></h2><h4 id="release-date-3rd-sept-2024" tabindex="-1">Release date: 3rd Sept 2024 <a class="header-anchor" href="#release-date-3rd-sept-2024" aria-label="Permalink to &quot;Release date: 3rd Sept 2024&quot;">​</a></h4><ul><li>Disabled legacy endpoints be default.</li><li>Removed support for Statamic 4.</li><li>Fixed some icons in dark mode.</li><li>Small fixes in Livewire components.</li><li>Improved the LfAvailabilityFilter component so that it requires less properties.</li><li>Added the live-availability data in the entries when using the regular Collection tag via a Hook.</li></ul>',47),l=[r];function n(s,d,c,h,u,p){return t(),a("div",null,l)}const b=e(o,[["render",n]]);export{m as __pageData,b as default};
